// 활용: 괄호 매칭
fun balanced(s: String): Boolean {
    val st = ArrayDeque<Char>()
    val pair = mapOf(')' to '(', ']' to '[', '}' to '{')
    for (c in s) when (c) {
        '(', '[', '{' -> st.addLast(c)
        ')', ']', '}' -> if (st.removeLastOrNull() != pair[c]) return false
    }
    return st.isEmpty()
}
